#include "HistoryMachine.h"
#include <stdio.h>
int main(void){ESCX_StateMachine m;HistoryData d;ESCX_BYTE_T active[ESCX_ACTIVE_BYTES(HistoryMachine_STATE_COUNT)];ESCX_BYTE_T valid[2];ESCX_BYTE_T history_bits[2*ESCX_ACTIVE_BYTES(HistoryMachine_STATE_COUNT)];ESCX_HistoryStorage h;d.value=0;h.valid=valid;h.bits=history_bits;h.slot_count=2U;h.bytes_per_slot=(ESCX_BYTE_T)ESCX_ACTIVE_BYTES(HistoryMachine_STATE_COUNT);HistoryMachine_Init(&m,&d,active,(ESCX_BYTE_T)sizeof(active),&h,(ESCX_StartTimerFunction)0,(ESCX_CancelTimerFunction)0);if(ESCX_StateMachineStart(&m)!=ESCX_STATUS_PROCESSED)return 1;if(ESCX_StateMachineSend(&m,HM_Next,(void*)0)!=ESCX_STATUS_PROCESSED)return 2;if(!ESCX_StateMachineIsInState(&m,HM_B))return 3;if(ESCX_StateMachineSend(&m,HM_Leave,(void*)0)!=ESCX_STATUS_PROCESSED)return 4;if(ESCX_StateMachineSend(&m,HM_ReturnShallow,(void*)0)!=ESCX_STATUS_PROCESSED)return 5;if(!ESCX_StateMachineIsInState(&m,HM_A)||ESCX_StateMachineIsInState(&m,HM_B))return 6;if(ESCX_StateMachineSend(&m,HM_Next,(void*)0)!=ESCX_STATUS_PROCESSED)return 7;if(ESCX_StateMachineSend(&m,HM_Leave,(void*)0)!=ESCX_STATUS_PROCESSED)return 8;if(ESCX_StateMachineSend(&m,HM_ReturnDeep,(void*)0)!=ESCX_STATUS_PROCESSED)return 9;if(!ESCX_StateMachineIsInState(&m,HM_B)||!ESCX_StateMachineIsInState(&m,HM_Nested))return 10;printf("shallow and deep history tests passed\n");return 0;}
